// Camera, UI, spawning, and input glue.
const byId=id=>document.getElementById(id);const keys=Object.create(null);let focus=new THREE.Vector3(0,100,650),orbitYaw=.32,orbitPitch=.34,orbitDistance=1450,drag=null,toastTimer=0;
function positionCamera(){const cp=Math.cos(orbitPitch);camera.position.set(focus.x+Math.sin(orbitYaw)*cp*orbitDistance,focus.y+Math.sin(orbitPitch)*orbitDistance,focus.z+Math.cos(orbitYaw)*cp*orbitDistance);camera.lookAt(focus)}positionCamera();
function notify(text){const el=byId('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function callSign(){return `SW${Math.floor(100+Math.random()*899)}`}
function renderAircraftList(){const list=byId('aircraftList');byId('aircraftCount').textContent=String(aircraft.length).padStart(2,'0');if(!aircraft.length){list.innerHTML='<div class="empty-state">No aircraft in range.<br><span>Spawn one to begin.</span></div>';return}list.innerHTML=aircraft.map((p,i)=>`<button class="aircraft-row ${selected===p?'selected':''}" data-index="${i}"><span class="plane-thumb">✈</span><span><strong>${p.callSign}</strong><small>${p.data.name}${p.alive?' · ACTIVE':' · INCIDENT'}</small></span><b class="row-health">${Math.round(p.damage)}%</b></button>`).join('');list.querySelectorAll('.aircraft-row').forEach(row=>row.onclick=()=>setSelected(aircraft[Number(row.dataset.index)]))}
function setSelected(p){selected=p;renderAircraftList();renderInspector()}
function renderInspector(){const root=byId('inspectContent');if(!selected){root.className='inspect-empty';root.innerHTML='<div class="reticle">⌖</div><strong>Select an aircraft</strong><span>Click any aircraft in the world<br>to inspect its systems.</span>';return}const p=selected;root.className='inspect-body';const health=Math.round(p.damage),status=!p.alive?'INCIDENT':health<45?'CRITICAL':health<80?'DEGRADED':'NOMINAL';root.innerHTML=`<div class="inspect-sub">${p.callSign} <span class="${health<45?'warn':''}">${status}</span></div><strong class="inspect-type">${p.data.name}</strong><div class="inspect-stats"><div class="stat-line"><span>STRUCTURAL INTEGRITY</span><b>${health}%</b></div><div class="condition-line"><i style="width:${health}%"></i></div><div class="stat-line"><span>INDICATED SPEED</span><b>${Math.round(p.speed)} KT</b></div><div class="stat-line"><span>ALTITUDE</span><b>${Math.max(0,Math.round(p.group.position.y*3.281)).toLocaleString()} FT</b></div><div class="stat-line"><span>PASSENGERS</span><b>${p.passengers}</b></div><div class="components-title">SYSTEMS</div>${Object.entries(p.components).map(([name,value])=>`<div class="component"><span>${name}</span><b class="${value<45?'warn':''}">${Math.round(value)}%</b></div>`).join('')}</div><div class="action-stack"><button class="action-btn primary" data-action="control">${controlled===p?'RELEASE CONTROL':'TAKE CONTROL'}</button><button class="action-btn" data-action="damage">SIMULATE DAMAGE</button><button class="action-btn" data-action="rescue">DISPATCH RESPONSE</button></div>`;root.querySelector('[data-action="control"]').onclick=()=>{controlled=controlled===p?null:p;focus.copy(p.group.position);notify(controlled?'PILOT CONTROL ENABLED':'PILOT CONTROL RELEASED');renderInspector()};root.querySelector('[data-action="damage"]').onclick=()=>damagePlane(p,12+Math.floor(Math.random()*18));root.querySelector('[data-action="rescue"]').onclick=()=>{spawnRescue(p);recordEvent(p,'EMERGENCY RESPONSE DISPATCHED');notify('RESCUE UNITS DISPATCHED TO '+p.callSign)}}
let selectedFleet=fleet[0];function renderFleet(){byId('fleetGrid').innerHTML=fleet.map((d,i)=>`<button class="fleet-card ${selectedFleet===d?'active':''}" data-fleet="${i}"><span class="fleet-art">✈</span><strong>${d.name}</strong><small>${d.type}</small></button>`).join('');byId('fleetGrid').querySelectorAll('.fleet-card').forEach(el=>el.onclick=()=>{selectedFleet=fleet[Number(el.dataset.fleet)];renderFleet()})}
function openSpawn(){byId('modalBackdrop').classList.add('open');renderFleet()}function closeSpawn(){byId('modalBackdrop').classList.remove('open')}
byId('spawnBtn').onclick=openSpawn;byId('closeModal').onclick=closeSpawn;byId('modalBackdrop').addEventListener('click',e=>{if(e.target===byId('modalBackdrop'))closeSpawn()});
const rangeLabels=[['altitude','altValue',v=>`${Number(v).toLocaleString()} ft`],['speed','speedValue',v=>`${v} kt`],['heading','headingValue',v=>`${v}°`],['condition','conditionValue',v=>`${v}%`],['passengers','passengerValue',v=>v]];for(const [input,label,format]of rangeLabels){const el=byId(input);el.addEventListener('input',()=>byId(label).textContent=format(el.value))}
byId('confirmSpawn').onclick=()=>{const p=makePlane(selectedFleet,{altitude:Number(byId('altitude').value),speed:Number(byId('speed').value),heading:Number(byId('heading').value),engine:byId('engineCondition').value,passengers:Number(byId('passengers').value)});p.callSign=callSign();p.damage=Number(byId('condition').value);Object.keys(p.components).forEach(k=>p.components[k]=p.damage);p.group.position.set(-300+(Math.random()-.5)*140,Math.max(8,p.altitude/3.281),1050+(Math.random()-.5)*350);p.velocity.set(0,0,0);aircraft.push(p);scene.add(p.group);setSelected(p);recordEvent(p,'AIRFRAME SPAWNED · '+p.data.name.toUpperCase());closeSpawn();notify(`${p.callSign} · ${p.data.name.toUpperCase()} SPAWNED`)};
function seedAircraft(){const p=makePlane(fleet[0],{altitude:420,speed:210,heading:270,passengers:128});p.callSign='SW248';p.group.position.set(60,420,890);p.velocity.set(-80,0,0);aircraft.push(p);scene.add(p.group);renderAircraftList()}seedAircraft();
window.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='KeyF'&&!byId('modalBackdrop').classList.contains('open'))openSpawn();if(e.code==='Escape'){closeSpawn();byId('helpPanel').classList.remove('open')}});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>Object.keys(keys).forEach(k=>keys[k]=false));
canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>4)drag.moved=true;if(drag.moved){orbitYaw-=dx*.005;orbitPitch=THREE.MathUtils.clamp(orbitPitch+dy*.004,-.05,1.35);positionCamera()}drag.lastX=e.clientX;drag.lastY=e.clientY});canvas.addEventListener('pointerup',()=>{drag=null});canvas.addEventListener('wheel',e=>{orbitDistance=THREE.MathUtils.clamp(orbitDistance*Math.exp(e.deltaY*.001),120,5000);positionCamera()},{passive:true});
