// Dual mobile joysticks: left controls move/throttle, right controls bank/pitch.
const joystick={move:{x:0,y:0},turn:{x:0,y:0}};
function bindJoystick(id,name){const pad=byId(id),base=pad.querySelector('.joystick-base'),knob=pad.querySelector('.joystick-knob');let pointerId=null;const update=(e)=>{const r=base.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),limit=r.width*.31,len=Math.hypot(dx,dy);const scale=len>limit?limit/len:1,x=dx*scale,y=dy*scale;joystick[name].x=x/limit;joystick[name].y=y/limit;knob.style.transform=`translate(${x}px,${y}px)`};pad.addEventListener('pointerdown',e=>{pointerId=e.pointerId;pad.setPointerCapture(pointerId);pad.classList.add('active');update(e);e.prevent.preventDefault?.()},{passive:false});pad.addEventListener('pointermove',e=>{if(e.pointerId===pointerId)update(e)});const reset=e=>{if(e.pointerId!==pointerId)return;pointerId=null;joystick[name].x=0;joystick[name].y=0;knob.style.transform='translate(0,0)';pad.classList.remove('active')};pad.addEventListener('pointerup',reset);pad.addEventListener('pointercancel',reset)}
bindJoystick('moveJoystick','move');bindJoystick('turnJoystick','turn');

