python3 - <<'EOF'
import re
s=open('style.css').read()
# remove comments and strings, keeping same length
def blank(m): return ' '*len(m.group(0))
t=re.sub(r'/\*.*?\*/',blank,s,flags=re.S)
t=re.sub(r'"[^"]*"',blank,t)
t=re.sub(r"'[^']*'",blank,t)
depth=0; stack=[]
for i,ch in enumerate(t):
    if ch=='(':
        depth+=1; stack.append(i)
    elif ch==')':
        if stack: stack.pop()
        depth-=1
        if depth<0: print('extra ) at',i, t[max(0,i-80):i+20]); depth=0
print('unclosed at:', stack)
for i in stack:
    print(repr(t[max(0,i-120):i+80]))
EOF

