import { spawn } from 'node:child_process';
import fs from 'node:fs';

const PORT = 9333;
const URL = 'http://127.0.0.1:8766/index.html';
const chrome = spawn('chromium', [
  '--headless=new', '--no-sandbox', '--disable-gpu', '--hide-scrollbars',
  '--touch-events=enabled', '--window-size=390,844', '--force-device-scale-factor=1',
  `--remote-debugging-port=${PORT}`,
  '--user-data-dir=/tmp/opencode/cdp-profile',
  '--host-resolver-rules=MAP fonts.googleapis.com 127.0.0.1, MAP fonts.gstatic.com 127.0.0.1',
  URL
], { stdio: 'ignore' });

const sleep = ms => new Promise(r => setTimeout(r, ms));
let targets;
for (let i = 0; i < 60; i++) {
  try { targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json(); if (targets.length) break; } catch {}
  await sleep(250);
}
const page = targets.find(t => t.type === 'page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
let id = 0; const pending = new Map();
ws.onmessage = ev => { const m = JSON.parse(ev.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
const send = (method, params = {}) => new Promise(res => { const i = ++id; pending.set(i, res); ws.send(JSON.stringify({ id: i, method, params })); });
const evalJs = async expression => {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (r.result?.exceptionDetails) throw new Error(JSON.stringify(r.result.exceptionDetails));
  return r.result?.result?.value;
};
const shot = async path => {
  const r = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path, Buffer.from(r.result.data, 'base64'));
};

await send('Runtime.enable'); await send('Page.enable');
for (let i = 0; i < 80; i++) {
  const ready = await evalJs(`typeof document.getElementById('spawnBtn').onclick === 'function'`).catch(() => false);
  if (ready) break;
  await sleep(250);
}
await sleep(1500);

const results = {};
results.touchUi = await evalJs(`document.body.classList.contains('touch-ui')`);
results.modalInitiallyClosed = await evalJs(`!document.getElementById('modalBackdrop').classList.contains('open')`);
await evalJs(`document.getElementById('spawnBtn').click()`);
await sleep(350);
results.opened = await evalJs(`document.getElementById('modalBackdrop').classList.contains('open')`);
await shot('/tmp/opencode/mobile-modal.png');

await evalJs(`document.getElementById('modalBackdrop').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:3,pointerType:'touch'}))`);
await sleep(250);
results.staysOpenOnBackdropTap = await evalJs(`document.getElementById('modalBackdrop').classList.contains('open')`);

await evalJs(`document.getElementById('closeModal').click()`);
await sleep(250);
results.closedByX = await evalJs(`!document.getElementById('modalBackdrop').classList.contains('open')`);

await evalJs(`document.getElementById('spawnBtn').click()`);
await sleep(300);
results.reopened = await evalJs(`document.getElementById('modalBackdrop').classList.contains('open')`);
await evalJs(`document.getElementById('closeModal').click()`);
await sleep(200);

results.helpClosedInitially = await evalJs(`!document.getElementById('helpPanel').classList.contains('open')`);
await evalJs(`document.getElementById('helpBtn').click()`);
await sleep(200);
results.helpOpened = await evalJs(`document.getElementById('helpPanel').classList.contains('open')`);
await shot('/tmp/opencode/mobile-help.png');
await evalJs(`document.getElementById('closeHelp').click()`);
await sleep(200);
results.helpClosedByX = await evalJs(`!document.getElementById('helpPanel').classList.contains('open')`);
await evalJs(`document.getElementById('helpBtn').click()`);
await sleep(200);
results.helpReopened = await evalJs(`document.getElementById('helpPanel').classList.contains('open')`);
await evalJs(`document.getElementById('closeHelp').click()`);

const rect = await evalJs(`(()=>{const r=document.getElementById('moveJoystick').getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}})()`);
const coordsBefore = await evalJs(`document.getElementById('coords').textContent`);
await evalJs(`(()=>{const p=document.getElementById('moveJoystick');p.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:11,pointerType:'touch',clientX:${rect.x + rect.w / 2},clientY:${rect.y + 12}}))})()`);
await sleep(100);
results.moveKnobActive = await evalJs(`document.querySelector('#moveJoystick .joystick-knob').style.transform`);
await sleep(900);
const coordsAfter = await evalJs(`document.getElementById('coords').textContent`);
results.cameraMoved = coordsBefore !== coordsAfter;
results.coordsBefore = coordsBefore; results.coordsAfter = coordsAfter;
await evalJs(`document.getElementById('moveJoystick').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:11,pointerType:'touch'}))`);
await sleep(150);
results.moveKnobReset = await evalJs(`document.querySelector('#moveJoystick .joystick-knob').style.transform`);

const r2 = await evalJs(`(()=>{const r=document.getElementById('turnJoystick').getBoundingClientRect();return {x:r.x,y:r.y,w:r.width,h:r.height}})()`);
await evalJs(`document.getElementById('turnJoystick').dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:12,pointerType:'touch',clientX:${r2.x + r2.w - 14},clientY:${r2.y + r2.h / 2}}))`);
await sleep(250);
results.turnKnobActive = await evalJs(`document.querySelector('#turnJoystick .joystick-knob').style.transform`);
results.turnPadActiveClass = await evalJs(`document.getElementById('turnJoystick').classList.contains('active')`);
await evalJs(`document.getElementById('turnJoystick').dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:12,pointerType:'touch'}))`);
await sleep(150);
results.turnKnobReset = await evalJs(`document.querySelector('#turnJoystick .joystick-knob').style.transform`);

const errors = await evalJs(`window.__errs ? window.__errs : 'none'`);
results.errors = errors;
console.log(JSON.stringify(results, null, 2));
ws.close();
chrome.kill();

